sysauto_script.script:
// RetentionGuard — scheduled daily dry-run cycle
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runRetentionGuardDailyDryRun() {
    try {
        var engine = new RetentionGuardEngine();
        var result = engine.runCycle(true);
        gs.info('RetentionGuard daily dry-run complete: run_id=' + result.run_id +
            ', tables=' + result.results.length);
    } catch (e) {
        gs.error('RetentionGuard daily dry-run failed: ' + e.message);
    }
})();
